-- What supabase/challenges.sql does, tried inside the rolled-back transaction
-- of a dry run: nothing here is kept.
--
--   set -a; . ./.env; set +a
--   PG_MODULE=/tmp/pg/node_modules/pg/lib/index.js \
--     node tools/apply_sql.mjs supabase/challenges.sql --dry --try=tools/challenges_try.sql --table=challenge_entries
--
-- After the live files (trust, tested, comments, builds, versions, follows,
-- discovery, designers), which the project has. Made-up accounts, made and
-- gone with the transaction: Ada designs (13 or over, a profile), Bob votes
-- and designs one too (13 or over, a profile), Ed votes (13 or over, no
-- profile), Cy is under 13, Dee was never asked. Every model a test model,
-- so the challenges here are test challenges, which no visitor's page shows.
-- Each statement is on one line: the dry run splits at a semicolon that ends
-- a line. Inside one transaction now() never moves, so a challenge is ended
-- by moving its days.
-- First, what the live functions answer before anything here is made: the gallery's first page, a visitor's, and the busiest designer's page. Compared at the end with the same questions.
create temp table before_ as select 'models' as what, md5(coalesce(string_agg(c::text, '|' order by n), '')) as said from (select c, row_number() over () as n from public.directory_models('{"sort": "top"}'::jsonb) c) x union all select 'designer', md5(coalesce(public.designer_page((select p.handle from public.people p join public.shared_models m on m.owner = p.account where m.published and m.listed and not m.test group by p.handle order by count(*) desc limit 1), false)::text, '')) union all select 'pick', md5(coalesce(public.gallery_pick(false)::text, ''));
create function pg_temp.tries(statement text) returns text language plpgsql as $$ begin execute statement; return 'allowed'; exception when others then return 'refused: ' || sqlerrm; end $$;
-- Any test challenge a flow left open is ended first: one at a time.
update public.challenges set ended_at = now() where test and ended_at is null;
insert into auth.users (id, instance_id, aud, role, email) values ('00000000-0000-4000-8000-0000000000c1', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'challenges-ada@resend.dev'), ('00000000-0000-4000-8000-0000000000c2', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'challenges-bob@resend.dev'), ('00000000-0000-4000-8000-0000000000c3', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'challenges-cy@resend.dev'), ('00000000-0000-4000-8000-0000000000c4', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'challenges-dee@resend.dev'), ('00000000-0000-4000-8000-0000000000c5', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'challenges-ed@resend.dev');
select public.answer_age('00000000-0000-4000-8000-0000000000c1', true)->>'over_13' as ada, public.answer_age('00000000-0000-4000-8000-0000000000c2', true)->>'over_13' as bob, public.answer_age('00000000-0000-4000-8000-0000000000c3', false)->>'over_13' as cy, public.answer_age('00000000-0000-4000-8000-0000000000c5', true)->>'over_13' as ed;
insert into public.people (account, handle, name) values ('00000000-0000-4000-8000-0000000000c1', 'challenges-try-ada', 'Ada Try'), ('00000000-0000-4000-8000-0000000000c2', 'challenges-try-bob', 'Bob Try');
-- Ada's models: a small house (40 parts, every lot in the set, Tested), a tower (40 parts, one lot short of the set), a big hall (500 parts), one by link only, one listed without her name, one never counted. Bob's shed. Cy's model by link (he cannot list).
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published) values ('ChallTry01', '00000000-0000-4000-8000-0000000000c1', 'Try house', 'Ada Try', 40, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('ChallTry02', '00000000-0000-4000-8000-0000000000c1', 'Try tower', 'Ada Try', 40, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('ChallTry03', '00000000-0000-4000-8000-0000000000c1', 'Try hall', 'Ada Try', 500, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('ChallTry04', '00000000-0000-4000-8000-0000000000c1', 'Try secret', 'Ada Try', 40, 100, false, null, true, now() - interval '3 days', true), ('ChallTry05', '00000000-0000-4000-8000-0000000000c1', 'Try nameless', null, 40, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('ChallTry06', '00000000-0000-4000-8000-0000000000c1', 'Try uncounted', 'Ada Try', 40, 100, true, now() - interval '3 days', true, now() - interval '3 days', true), ('ChallTry07', '00000000-0000-4000-8000-0000000000c2', 'Try shed', 'Bob Try', 30, 100, true, now() - interval '2 days', true, now() - interval '2 days', true), ('ChallTry08', '00000000-0000-4000-8000-0000000000c3', 'Try by Cy', null, 30, 100, false, null, true, now() - interval '2 days', true);
insert into public.share_versions (model, n, at, parts, bytes) select id, 1, created_at, parts, 100 from public.shared_models where id like 'ChallTry%';
insert into public.share_tests (model, n, app, file_hash, parts, steps, tests, passed) values ('ChallTry01', 1, '0.3.0', repeat('a', 64), 40, 4, '{"stands": {"ok": true}, "steps": {"ok": true}, "parts": {"ok": true}, "whole": {"ok": true}}', true), ('ChallTry02', 1, '0.3.0', repeat('b', 64), 40, 4, '{"stands": {"ok": true}, "steps": {"ok": true}, "parts": {"ok": true}, "whole": {"ok": true}}', true), ('ChallTry07', 1, '0.3.0', repeat('c', 64), 30, 3, '{"stands": {"ok": true}, "steps": {"ok": true}, "parts": {"ok": true}, "whole": {"ok": true}}', true);
-- What each needs (model_needs, as api/share.js keeps it): the house 30 red 3001 and 10 blue 3003; the tower 30 red 3001 and 10 yellow 3003 (the set has 4 yellow); the hall 500 red 3001; the shed 30 white 3001.
select public.owned_keep_needs('ChallTry01', '[{"part": "3001", "colour": 4, "qty": 30}, {"part": "3003", "colour": 1, "qty": 10}]') as house, public.owned_keep_needs('ChallTry02', '[{"part": "3001", "colour": 4, "qty": 30}, {"part": "3003", "colour": 14, "qty": 10}]') as tower, public.owned_keep_needs('ChallTry03', '[{"part": "3001", "colour": 4, "qty": 500}]') as hall, public.owned_keep_needs('ChallTry05', '[{"part": "3001", "colour": 4, "qty": 30}]') as nameless, public.owned_keep_needs('ChallTry07', '[{"part": "3001", "colour": 15, "qty": 30}]') as shed;
-- Setting one: refused when it ends before today, a set with no parts, or a day shared with another of its kind.
select public.challenge_set('Try past', 'Brief', current_date - 10, current_date - 1, test => true)->>'refused' as "ends before today", public.challenge_set('Try empty set', 'Brief', current_date, current_date + 10, set_number => '1-1', set_name => 'Nothing', set_parts => '[]', test => true)->>'refused' as "a set with no parts";
select public.challenge_set('Try October', 'Build a house with the parts of one set, under 100 parts, Tested.', current_date - 1, current_date + 12, most_parts => 100, set_number => '6080-1', set_name => 'Try King''s Castle', set_parts => '[{"part": "3001", "colour": 4, "qty": 60}, {"part": "3003", "colour": 1, "qty": 20}, {"part": "3003", "colour": 14, "qty": 4}, {"part": "3001", "colour": 15, "qty": 30}]', tested => true, test => true) ?| array['challenge'] as "set";
select public.challenge_set('Try overlap', 'Brief', current_date + 5, current_date + 20, test => true)->>'refused' as "a day shared", public.challenge_set('Try overlap', 'Brief', current_date + 5, current_date + 20, test => true)->'with'->>'title' as "with";
select pg_temp.tries($q$select public.challenge_set('Try too long', 'Brief', current_date + 100, current_date + 200, test => true)$q$) as "64 days or more";
select title, starts_on = current_date - 1 as "from yesterday", ends_on - starts_on as days, most_parts, set_number, tested, test, (select count(*) from public.challenge_set_parts s where s.challenge = c.id) as "set lots" from public.challenges c where c.title = 'Try October';
-- It is the one open for tests, and a visitor's page does not show it.
select (public.challenge_open(true)).title as "open for tests", (public.challenge_shown(true)).title as "a tests page shows", coalesce((public.challenge_shown(false)).test, false) as "a visitor's page shows a test one";
-- The rules, checked: the house keeps all three; the tower is one lot short (6 yellow 3003); the hall has 500 parts and 440 red short, and is not Tested; the uncounted one does not keep the set's rule.
select x.id, (c->>'ok') as ok, c->'parts'->>'ok' as parts, c->'set'->>'ok' as "set", c->'set'->>'short_lots' as short, c->'set'->'short'->0 as "most short", c->'tested'->>'ok' as tested, c->'set'->>'counted' as counted from (select m.id, public.challenge_check((select id from public.challenges where title = 'Try October'), m.id) as c from public.shared_models m where m.id in ('ChallTry01', 'ChallTry02', 'ChallTry03', 'ChallTry06') order by m.id) x;
-- Entering: refused in words for each reason; the house goes in.
select public.challenge_enter('00000000-0000-4000-8000-0000000000c2', 'ChallTry01', 'hand')->>'refused' as "Bob enters Ada's", public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'NoSuchMode', 'hand')->>'refused' as "no model", public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallTry04', 'hand')->>'refused' as "by link only", public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallTry05', 'hand')->>'refused' as "not credited", public.challenge_enter('00000000-0000-4000-8000-0000000000c3', 'ChallTry08', 'hand')->>'refused' as "Cy, under 13";
select public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallTry02', 'hand')->>'refused' as "the tower", public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallTry03', 'assistant')->'check' as "the hall's check";
select pg_temp.tries($q$select public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallTry01', 'robot')$q$) as "a way that is neither";
select public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallTry01', 'hand') - 'check' as "the house, by hand", public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallTry01', 'assistant') as "the house again";
-- Bob's shed with the assistant; Dee, never asked, is refused before anything else of hers is read.
update public.shared_models set owner = '00000000-0000-4000-8000-0000000000c4' where id = 'ChallTry06';
select public.challenge_enter('00000000-0000-4000-8000-0000000000c2', 'ChallTry07', 'assistant')->>'way' as "Bob's shed", public.challenge_enter('00000000-0000-4000-8000-0000000000c4', 'ChallTry06', 'hand')->>'refused' as "Dee, not asked";
update public.shared_models set owner = '00000000-0000-4000-8000-0000000000c1' where id = 'ChallTry06';
-- The feed: Ed follows Ada, and his feed says her house went in, by hand, beside the models she listed. Fay, who is not a test account, follows her too and sees none of it: test models, a test challenge.
insert into auth.users (id, instance_id, aud, role, email) values ('00000000-0000-4000-8000-0000000000c6', '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'challenges-fay@example.com');
select public.answer_age('00000000-0000-4000-8000-0000000000c6', true)->>'over_13' as fay;
select public.follow_person('00000000-0000-4000-8000-0000000000c5', 'challenges-try-ada', true) as "Ed follows Ada", public.follow_person('00000000-0000-4000-8000-0000000000c6', 'challenges-try-ada', true) as "Fay follows Ada";
select f.kind, f.item->>'name' as name, f.item->>'title' as title, f.item->>'way' as way, f.item->'by'->>'handle' as by from public.feed_rows('00000000-0000-4000-8000-0000000000c5', now() - interval '90 days', now()) f order by f.kind, f.item->>'name';
select public.feed_of('00000000-0000-4000-8000-0000000000c5')->'rows'->0->>'kind' as "Ed's newest", public.feed_count('00000000-0000-4000-8000-0000000000c5') as "Ed's count", (select count(*) from public.feed_rows('00000000-0000-4000-8000-0000000000c6', now() - interval '90 days', now())) as "Fay's feed";
-- A model that is not a test account's enters only a challenge that is not a test one: none is open for it here.
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published) values ('ChallReal1', '00000000-0000-4000-8000-0000000000c1', 'Try real', 'Ada Try', 40, 100, true, now(), false, now(), true);
select case when (public.challenge_open(false)).id is null then public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallReal1', 'hand') ->> 'refused' else 'a real one is open' end as "not a test model", (select count(*) from public.challenge_entries e where e.challenge = (select id from public.challenges where title = 'Try October')) as entries;
