-- What the model's page tells its owner, and tells nobody else.
select public.challenge_for_model('00000000-0000-4000-8000-0000000000c1', 'ChallTry01')->'entry'->>'way' as "the house's entry", public.challenge_for_model('00000000-0000-4000-8000-0000000000c1', 'ChallTry02')->'check'->>'ok' as "the tower keeps the rules", public.challenge_for_model('00000000-0000-4000-8000-0000000000c2', 'ChallTry01') as "asked by Bob";
