select public.challenge_vote('00000000-0000-4000-8000-0000000000c2', (select id from public.challenges where title = 'Try October'), 'ChallTry01', true) as "Bob for the house", public.challenge_vote('00000000-0000-4000-8000-0000000000c5', (select id from public.challenges where title = 'Try October'), 'ChallTry01', true)->>'voted' as "Ed for the house", public.challenge_vote('00000000-0000-4000-8000-0000000000c5', (select id from public.challenges where title = 'Try October'), 'ChallTry07', true)->>'voted' as "Ed for the shed";
select public.challenge_vote('00000000-0000-4000-8000-0000000000c2', (select id from public.challenges where title = 'Try October'), 'ChallTry01', true) as "Bob again";
select public.challenge_mine('00000000-0000-4000-8000-0000000000c2', (select id from public.challenges where title = 'Try October')) as "Bob's", public.challenge_mine('00000000-0000-4000-8000-0000000000c3', (select id from public.challenges where title = 'Try October'))->>'may_vote' as "Cy may vote";
-- The page while it runs: two entries, the hand's first, each a card, keeping the rules, and no votes shown.
select e->>'model' as model, e->>'way' as way, e->>'keeps' as keeps, e->'votes' as votes, e->'card'->>'name' as card from jsonb_array_elements(public.challenge_page(true)->'entries') e;
select p->>'title' as title, p->>'state' as state, p->'rules' as rules, jsonb_array_length(p->'winners') as winners from (select public.challenge_page(true) as p) x;
-- Not settled while it runs.
select public.challenge_settle((select id from public.challenges where title = 'Try October')) as "settled while it runs";
-- A newer version of the house that is not Tested: it no longer keeps the rules, says so, and a vote for it is refused.
insert into public.share_versions (model, n, at, parts, bytes) values ('ChallTry01', 2, now(), 40, 100);
select e->>'model' as model, e->>'keeps' as keeps from jsonb_array_elements(public.challenge_page(true)->'entries') e;
select public.challenge_vote('00000000-0000-4000-8000-0000000000c5', (select id from public.challenges where title = 'Try October'), 'ChallTry01', true)->>'refused' as "a vote for it now";
insert into public.share_tests (model, n, app, file_hash, parts, steps, tests, passed) values ('ChallTry01', 2, '0.3.0', repeat('d', 64), 40, 4, '{"stands": {"ok": true}, "steps": {"ok": true}, "parts": {"ok": true}, "whole": {"ok": true}}', true);
select e->>'model' as model, e->>'keeps' as keeps from jsonb_array_elements(public.challenge_page(true)->'entries') e;
-- Taking an entry back: Bob's shed, and Ed's vote for it with it; then in again.
select public.challenge_withdraw('00000000-0000-4000-8000-0000000000c2', 'ChallTry07') as "Bob takes his back", public.challenge_withdraw('00000000-0000-4000-8000-0000000000c2', 'ChallTry07') as "again", (select count(*) from public.challenge_votes v where v.model = 'ChallTry07') as "votes for it";
select public.challenge_enter('00000000-0000-4000-8000-0000000000c2', 'ChallTry07', 'assistant')->>'entered' as "in again", public.challenge_vote('00000000-0000-4000-8000-0000000000c5', (select id from public.challenges where title = 'Try October'), 'ChallTry07', true)->>'voted' as "Ed votes again";
-- At most three of a designer's.
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published) select 'ChallMore' || n, '00000000-0000-4000-8000-0000000000c1', 'Try more ' || n, 'Ada Try', 10, 100, true, now(), true, now(), true from generate_series(1, 3) n;
insert into public.share_versions (model, n, at, parts, bytes) select 'ChallMore' || n, 1, now(), 10, 100 from generate_series(1, 3) n;
insert into public.share_tests (model, n, app, file_hash, parts, steps, tests, passed) select 'ChallMore' || n, 1, '0.3.0', repeat('e', 64), 10, 1, '{"stands": {"ok": true}, "steps": {"ok": true}, "parts": {"ok": true}, "whole": {"ok": true}}', true from generate_series(1, 3) n;
select public.owned_keep_needs('ChallMore' || n, '[{"part": "3001", "colour": 4, "qty": 10}]') from generate_series(1, 3) n;
select public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallMore1', 'assistant')->>'entered' as second, public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallMore2', 'assistant')->>'entered' as third, public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallMore3', 'assistant')->>'refused' as fourth;
-- A designer taken out: their entry leaves the page, and nobody can vote for it.
insert into public.barred_accounts (account, reason) values ('00000000-0000-4000-8000-0000000000c2', 'Try');
select (select count(*) from jsonb_array_elements(public.challenge_page(true)->'entries') e where e->>'model' = 'ChallTry07') as "Bob's shed on the page", public.challenge_vote('00000000-0000-4000-8000-0000000000c1', (select id from public.challenges where title = 'Try October'), 'ChallTry07', true)->>'refused' as "a vote for it";
delete from public.barred_accounts where account = '00000000-0000-4000-8000-0000000000c2';
-- When it ends (its days moved back): no more entries or votes; settled once, the house by hand with 2 votes, the shed with the assistant with 1 (Ada's second entry has none, so it does not win).
update public.challenges set starts_on = current_date - 20, ends_on = current_date - 1 where title = 'Try October';
select public.challenge_vote('00000000-0000-4000-8000-0000000000c2', (select id from public.challenges where title = 'Try October'), 'ChallMore1', true)->>'refused' as "a vote after", public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallMore3', 'hand')->>'refused' as "an entry after", public.challenge_withdraw('00000000-0000-4000-8000-0000000000c1', 'ChallTry01') as "taken back after";
select public.challenge_settle((select id from public.challenges where title = 'Try October')) as settled, public.challenge_settle((select id from public.challenges where title = 'Try October')) as "settled again";
select w.way, w.model, w.votes from public.challenge_winners w join public.challenges c on c.id = w.challenge where c.title = 'Try October' order by w.way desc;
select p->>'state' as state, p->>'settled' as settled, p->'winners' as winners, (select string_agg((e->>'model') || ' ' || (e->>'votes'), ', ' order by e->>'way' desc, (e->>'votes')::int desc) from jsonb_array_elements(p->'entries') e) as "entries and votes" from (select public.challenge_page(true) as p) x;
-- The wins, for Ada's page and for the cards; a visitor's (no tests) has none of a test challenge.
select w->>'title' as title, w->>'way' as way, w->>'model' as model, w->>'votes' as votes from public.challenge_wins('00000000-0000-4000-8000-0000000000c1', null, true) w;
select (select count(*) from public.challenge_wins(null, array['ChallTry01', 'ChallTry07'], true)) as "on the cards", (select count(*) from public.challenge_wins('00000000-0000-4000-8000-0000000000c1', null, false)) as "a visitor's";
-- A tie goes to the one entered first: a second test challenge, two entries, one vote each.
select public.challenge_set('Try November', 'A tie', current_date, current_date + 5, test => true)->>'challenge' is not null as "set";
select public.challenge_enter('00000000-0000-4000-8000-0000000000c2', 'ChallTry07', 'hand')->>'entered' as "Bob's shed first";
update public.challenge_entries set at = now() - interval '1 hour' where model = 'ChallTry07' and challenge = (select id from public.challenges where title = 'Try November');
select public.challenge_enter('00000000-0000-4000-8000-0000000000c1', 'ChallTry01', 'hand')->>'entered' as "Ada's house second";
select public.challenge_vote('00000000-0000-4000-8000-0000000000c5', (select id from public.challenges where title = 'Try November'), 'ChallTry01', true)->>'voted' as "Ed for the house", public.challenge_vote('00000000-0000-4000-8000-0000000000c1', (select id from public.challenges where title = 'Try November'), 'ChallTry07', true)->>'voted' as "Ada for the shed";
select public.challenge_end((select id from public.challenges where title = 'Try November')) as "ended by the owner", public.challenge_end((select id from public.challenges where title = 'Try November')) as "again";
select public.challenge_settle((select id from public.challenges where title = 'Try November')) as settled;
select (select w.model from public.challenge_winners w join public.challenges c on c.id = w.challenge where c.title = 'Try November' and w.way = 'hand') as "the tie's winner, entered first", (select w.votes from public.challenge_winners w join public.challenges c on c.id = w.challenge where c.title = 'Try November' and w.way = 'hand') as votes;
-- The admin's list: both, the newest first, with their counts and winners.
select l->>'title' as title, l->>'state' as state, l->'entries' as entries, l->'votes' as votes, jsonb_array_length(l->'winners') as winners from public.challenge_list(true) l where l->>'title' like 'Try %';
-- Nobody but the server: no grant on the tables to any key, the service role's included; row security on; the functions the service role's alone.
select count(*) as "grants on the tables to anon, authenticated or service_role" from information_schema.role_table_grants where table_schema = 'public' and table_name in ('challenges', 'challenge_set_parts', 'challenge_entries', 'challenge_votes', 'challenge_winners') and grantee in ('anon', 'authenticated', 'service_role');
select string_agg(relname || ' ' || relrowsecurity, ', ' order by relname) as "row security" from pg_class where relname in ('challenges', 'challenge_set_parts', 'challenge_entries', 'challenge_votes', 'challenge_winners') and relkind = 'r';
select count(*) filter (where has_function_privilege('anon', p.oid, 'execute')) as anon, count(*) filter (where has_function_privilege('authenticated', p.oid, 'execute')) as authenticated, count(*) filter (where has_function_privilege('service_role', p.oid, 'execute')) as service_role, count(*) as functions from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname like 'challenge%';
-- How long it takes, on a big month: 600 entries by 300 designers, each of whom votes in both groups (600 votes), each model needing 40 lots against a set of 400; best of three.
insert into auth.users (id, instance_id, aud, role, email) select ('00000000-0000-4000-8000-0000000' || lpad(n::text, 5, '0'))::uuid, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'challenges-many-' || n || '@resend.dev' from generate_series(1, 300) n;
select count(*) as "300 said 13 or over" from (select public.answer_age(('00000000-0000-4000-8000-0000000' || lpad(n::text, 5, '0'))::uuid, true) from generate_series(1, 300) n) x;
select public.challenge_set('Try big', 'Many', current_date, current_date + 20, most_parts => 1000, set_number => '9999-1', set_name => 'Try big set', set_parts => (select jsonb_agg(jsonb_build_object('part', 'p' || k, 'colour', k % 10, 'qty', 50)) from generate_series(1, 400) k), tested => true, test => true)->>'challenge' is not null as "a big one";
insert into public.shared_models (id, owner, name, author, parts, bytes, listed, listed_at, test, created_at, published) select 'ChBig' || lpad(n::text, 5, '0'), ('00000000-0000-4000-8000-0000000' || lpad((1 + n % 300)::text, 5, '0'))::uuid, 'Big ' || n, 'Many', 200, 100, true, now(), true, now(), true from generate_series(1, 600) n;
insert into public.share_versions (model, n, at, parts, bytes) select 'ChBig' || lpad(n::text, 5, '0'), 1, now(), 200, 100 from generate_series(1, 600) n;
insert into public.share_tests (model, n, app, file_hash, parts, steps, tests, passed) select 'ChBig' || lpad(n::text, 5, '0'), 1, '0.3.0', repeat('f', 64), 200, 10, '{"stands": {"ok": true}, "steps": {"ok": true}, "parts": {"ok": true}, "whole": {"ok": true}}', true from generate_series(1, 600) n;
insert into public.model_needs (model, part, colour, qty) select 'ChBig' || lpad(n::text, 5, '0'), 'p' || (1 + (n * 7 + k) % 400), (1 + (n * 7 + k) % 400) % 10, 5 from generate_series(1, 600) n, generate_series(1, 40) k on conflict do nothing;
insert into public.model_needs_kept (model, pieces) select 'ChBig' || lpad(n::text, 5, '0'), 200 from generate_series(1, 600) n;
create function pg_temp.entered() returns text language plpgsql as $$ declare t0 timestamptz := clock_timestamp(); n integer := 0; begin for i in 1..600 loop if public.challenge_enter(('00000000-0000-4000-8000-0000000' || lpad((1 + i % 300)::text, 5, '0'))::uuid, 'ChBig' || lpad(i::text, 5, '0'), case when i % 2 = 0 then 'hand' else 'assistant' end) ? 'entered' then n := n + 1; end if; end loop; return format('%s entered, %s ms each', n, round(extract(epoch from clock_timestamp() - t0) * 1000 / 600, 2)); end $$;
select pg_temp.entered() as "600 entries";
insert into public.challenge_votes (challenge, way, voter, model) select e.challenge, e.way, ('00000000-0000-4000-8000-0000000' || lpad(v::text, 5, '0'))::uuid, (array_agg(e.model order by md5(e.model || v)))[1] from public.challenge_entries e cross join generate_series(1, 300) v where e.challenge = (select id from public.challenges where title = 'Try big') group by e.challenge, e.way, v;
analyze public.challenge_entries;
analyze public.challenge_votes;
create function pg_temp.best() returns text language plpgsql as $$ declare t0 timestamptz; a numeric := 1e9; b numeric := 1e9; c numeric := 1e9; d numeric := 1e9; big bigint := (select id from public.challenges where title = 'Try big'); begin for i in 1..3 loop t0 := clock_timestamp(); perform public.challenge_page(true); a := least(a, extract(epoch from clock_timestamp() - t0) * 1000); t0 := clock_timestamp(); perform public.challenge_check(big, 'ChBig00001'); b := least(b, extract(epoch from clock_timestamp() - t0) * 1000); t0 := clock_timestamp(); perform public.challenge_vote('00000000-0000-4000-8000-000000000001', big, 'ChBig00002', true); c := least(c, extract(epoch from clock_timestamp() - t0) * 1000); t0 := clock_timestamp(); perform public.challenge_mine('00000000-0000-4000-8000-000000000001', big); d := least(d, extract(epoch from clock_timestamp() - t0) * 1000); end loop; return format('page %s ms, one check %s ms, a vote %s ms, mine %s ms (best of three)', round(a, 1), round(b, 1), round(c, 1), round(d, 1)); end $$;
select jsonb_array_length(public.challenge_page(true)->'entries') as "entries on the page", (select count(*) from public.challenge_votes where challenge = (select id from public.challenges where title = 'Try big')) as votes, pg_temp.best() as timings;
update public.challenges set starts_on = current_date - 21, ends_on = current_date - 1 where title = 'Try big';
create function pg_temp.settled() returns text language plpgsql as $$ declare t0 timestamptz := clock_timestamp(); begin perform public.challenge_settle((select id from public.challenges where title = 'Try big')); return format('settled in %s ms', round(extract(epoch from clock_timestamp() - t0) * 1000, 1)); end $$;
select pg_temp.settled() as "the big month";
select (select count(*) from public.challenge_winners w where w.challenge = (select id from public.challenges where title = 'Try big')) as winners;
-- And what the live functions answer is the same as before anything here was made.
select b.what, b.said = a.said as "the same" from before_ b join (select 'models' as what, md5(coalesce(string_agg(c::text, '|' order by n), '')) as said from (select c, row_number() over () as n from public.directory_models('{"sort": "top"}'::jsonb) c) x union all select 'designer', md5(coalesce(public.designer_page((select p.handle from public.people p join public.shared_models m on m.owner = p.account where m.published and m.listed and not m.test group by p.handle order by count(*) desc limit 1), false)::text, '')) union all select 'pick', md5(coalesce(public.gallery_pick(false)::text, ''))) a on a.what = b.what
